```ts
/** A tag whose value is several named fields on one line, e.g. `atomaton:ended=done answers=12 run=34`. */
function makeCompoundTag<T>(
  key: string,
  valuePattern: string,
  parse: (match: RegExpExecArray) => T | undefined,
  render: (value: T) => string,
  search: (value: T) => string,
): AtomatonTag<T> {
  const pattern = `<!--\\s*${TAG_PREFIX}${key}=(?:${valuePattern})\\s*-->`;
  EVERY_TAG_PATTERN.push(pattern);
  const re = new RegExp(`<!--\\s*${TAG_PREFIX}${key}=(${valuePattern})\\s*-->`);
  return {
    marker: `${TAG_PREFIX}${key}`,
    write: (value) => `<!-- ${TAG_PREFIX}${key}=${render(value)} -->`,
    read: (text) => { const m = re.exec(text); return m ? parse(m) : undefined; },
    has: (text) => re.test(text),
    search: (value) => search(value),
  };
}
```

