  /** The comment id rides beside the body; `id` orders the asks. */
  const at = (id: number, entry: ThreadEntry): IdentifiedComment => ({ id, ...entry });

  const A = 101; // the ask the dispatch quotes
  const newer = 200; // any ask newer than A

